def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate groups of nested parentheses from a given string.
    :param paren_string: A string containing parentheses.
    :return: A list of strings, where each string represents a separate group.
    """
    groups = []
    group = ""
    stack = []
    for char in paren_string:
        if char == "(":
            stack.append(char)
        elif char == ")":
            if len(stack) > 0 and stack[-1] == "(":
                stack.pop()
                group += char
            else:
                raise ValueError("Unbalanced parentheses")
        else:
            group += char
        if len(stack) == 0:
            groups.append(group)
            group = ""
    if len(stack) > 0:
        raise ValueError("Unbalanced parentheses")
    return groups

