def verify_isbn(isbn: str) -> str:
    isbn = isbn.replace("-", "")
    checksum = 0
    for i, digit in enumerate(isbn[:-1]):
        if i % 2 == 0:
            checksum += int(digit)
        else:
            checksum += int(digit) * 3
    checksum = (10 - (checksum % 10)) % 10
    if isbn[-1] == str(checksum):
        return "Right"
    else:
        return isbn[:-1] + str(checksum)

