    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(x, int) or n < 0 or k < 1 or x < 1:
        raise ValueError("Invalid input")

    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(min(i, k)):
            dp[i] += dp[i - j * x]

    return dp[n]

