def preorder_traversal(inorder: str, postorder: str) -> str:
    inorder_indices = {c: i for i, c in enumerate(inorder)}
    root = postorder[-1]
    inorder_root = inorder_indices[root]
    left_subtree = inorder[:inorder_root]
    right_subtree = inorder[inorder_root+1:]
    left_subtree_postorder = postorder[:len(left_subtree)]
    right_subtree_postorder = postorder[len(left_subtree):-1]
    return preorder_traversal(left_subtree, left_subtree_postorder) + preorder_traversal(right_subtree, right_subtree_postorder)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder or len(inorder) != len(postorder):
        raise ValueError("Invalid input")

    preorder = []

    # Build the tree from inorder and postorder traversals
    root = len(inorder) - 1
    preorder.append(inorder[root])

    # Recursively traverse the tree and append nodes to preorder
    for i in range(root - 1, -1, -1):
        if inorder[i] == preorder[-1]:
            continue
        else:
            preorder.append(inorder[i])
            break

    for i in range(root, -1, -1):
        if postorder[i] in preorder:
            continue
        else:
            preorder.append(postorder[i])
            break

    return "".join(preorder)

def preorder_traversal(inorder, postorder):
    if len(inorder) == 0:
        return ""
    root = postorder[-1]
    i = len(inorder) - 1
    while inorder[i] != root:
        i -= 1
    left = inorder[:i]
    right = inorder[i+1:]
    return root + preorder_traversal(left, postorder[:-1]) + preorder_traversal(right, postorder[len(left):len(postorder)-1])

